func (q *Queries) ListSourceBindings(ctx context.Context, arg ListSourceBindingsParams) ([]SourceBinding, error) {
	rows, err := q.db.Query(ctx, listSourceBindings, arg.TenantID, arg.SourceSpecID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SourceBinding{}
	for rows.Next() {
		var i SourceBinding
		if err := rows.Scan(
			&i.TenantID,
			&i.ID,
			&i.SourceSpecID,
			&i.ScopeType,
			&i.ScopeKey,
			&i.ExpansionKey,
			&i.ResolvedPath,
			&i.SourceSystem,
			&i.AssetID,
			&i.LayerID,
			&i.State,
			&i.LastSeenCommit,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

